const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '选择题第1题' },
      { kind: 'text', payload: '选择题第2题' },
      { kind: 'text', payload: '填空题第3题' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var items = ['选择题第1题', '选择题第2题', '填空题第3题'];
    var marginX = Math.max(32, Math.min(64, Math.round(W * 0.08)));
    var fontSize = 18;
    var y = Math.max(56, Math.round(H * 0.16));
    var children = [];
    for (var i = 0; i < items.length; i++) {
      var m = (metrics && metrics[i]) ? metrics[i] : null;
      var lh = (m && typeof m.height === 'number' && m.height > 0) ? m.height : fontSize * 1.3;
      children.push({
        type: 'label',
        text: items[i],
        x: marginX,
        y: y,
        fontSize: fontSize,
        fill: '#111111',
        textAnchor: 'start'
      });
      y += Math.max(Math.round(lh * 1.7), 44);
    }
    return {
      schemaVersion: 1,
      sceneId: 'clean-questions',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [],
      root: { type: 'group', children: children }
    };
  }
};
